const cfg = $('Config (EDIT ME per role)').first().json;
const input = $input.first().json;

const resumeText = input.resumeText || '';

const prompt = `
You are a recruitment screening assistant.

Evaluate this candidate resume against the job/role configuration below.

JOB / ROLE CONFIGURATION:
${JSON.stringify(cfg, null, 2)}

CANDIDATE RESUME:
${resumeText}

Return ONLY valid JSON in exactly this format:
{
  "score": 75,
  "reason": "Brief explanation of why the candidate received this score."
}

Rules:
- Score must be an integer from 0 to 100.
- Evaluate based on the role requirements, skills, experience, education, and relevant projects.
- Do not invent candidate experience.
- Keep the reason concise but informative.
`;

const body = {
  systemInstruction: {
    parts: [{
      text: "You are a precise candidate screening assistant. Return only valid JSON."
    }]
  },
  contents: [{
    role: "user",
    parts: [{
      text: prompt
    }]
  }],
  generationConfig: {
    responseMimeType: "application/json"
  }
};

try {
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent",
    headers: {
      "x-goog-api-key": cfg.gemini_api_key,
      "Content-Type": "application/json"
    },
    body,
    json: true
  });

  const raw = res.candidates?.[0]?.content?.parts?.[0]?.text || "";

  const parsed = JSON.parse(
    raw.replace(/```json|```/g, "").trim()
  );

  return [{
    json: {
      score: Number(parsed.score),
      reason: String(parsed.reason || "")
    }
  }];

} catch (error) {

  return [{
    json: {
      success: false,
      statusCode: error.statusCode,
      message: error.message,
      response: error.response
    }
  }];
}

const input = $input.first().json;
const base = $('Parse Candidate Info').first().json;

return [{
  json: {
    name: base.name,
    email: base.email,
    score: Number(input.score) || 0,
    reason: input.reason || 'No reason returned'
  }
}];

const rows = $input.all().map(i => i.json);
const email = String($('Parse Score').first().json["email"]).toLowerCase();

const mine = rows.filter(r => String(r["Candidate Email"]).toLowerCase() === email);
const myRow = mine[mine.length - 1];
const day = myRow ? String(myRow["Date"]).slice(0, 10) : $now.toFormat('yyyy-MM-dd');

const sameDay = rows.filter(r =>
  String(r["Date"]).slice(0, 10) === day && Number(r["Score"]) >= 70
);

let position = sameDay.findIndex(r => r === myRow) + 1;
if (position === 0) position = sameDay.length + 1;

return [{ json: { position, slot_offset: Math.floor((position - 1) / 10) } }];
